    } else {
        const std::vector<std::string> muestras{
            "[ grupo rojo }",
            "{ grupo azul 9[10;0] 0[0;0] 4[2;7] }",
            "{ grupo verde 3[1;2]",
            "{ equipo verde }",
            "{ grupo verde 10[1;0] }"
        };
        for (const std::string& texto : muestras) {
            std::istringstream entrada{texto};
            const bool aceptado = leer_grupo(entrada, destino);
            mostrar(aceptado, destino);
        }
        std::istringstream entrada{
            "{ grupo rojo 9[0;1] }{ grupo verde 9[2;0] }"
        };
        bool aceptado = leer_grupo(entrada, destino);
        mostrar(aceptado, destino);
        std::cout << "AperturaPendiente:" << (entrada.peek() == '{') << '\n';
        aceptado = leer_grupo(entrada, destino);
        mostrar(aceptado, destino);
    }
    return 0;
}
